        void OnDestroy(){Application.logMessageReceived-=Log;}
        public static string Payload(LocalCafeBackend b,string kind,string choice=null,string cat=Cat,int slot=1)=>JsonUtility.ToJson(new PythonShiftCommand{kind=kind,choice=choice,cat_id=cat,save_slot=slot,save_id=slot.ToString(),working_cats=b.Simulation.State.cats.Where(c=>c.activity=="cafe" && c.health=="healthy").Select(c=>c.id).ToArray(),request_id=Guid.NewGuid().ToString("N"),instance_id=b.Simulation.State.instance_id,expected_revision=b.Simulation.State.revision});
        public static CafeResponse Raw(LocalCafeBackend b,string json){CafeResponse reply=null;var run=b.Request("/commands",json,r=>reply=r);while(run.MoveNext()){}return reply;}
        public static CafeResponse Send(LocalCafeBackend b,string kind,string choice=null,string cat=Cat,int slot=1)=>Raw(b,Payload(b,kind,choice,cat,slot));
        public static void Good(LocalCafeBackend b,string kind,string choice=null,string cat=Cat,int slot=1){var r=Send(b,kind,choice,cat,slot);if(r.result!=UnityWebRequest.Result.Success)throw new Exception(kind+": "+r.error);}
        static void ClearStore(LocalCafeBackend b){if(b.Simulation.StoreEventWaiting)Good(b,"resolve_store_event",b.Simulation.CurrentStoreEvent.type=="trouble"?"patch":"decline");}
        public static int BackendChecks(string folder,bool restart)
