            Good(b,"new_game","free");b.BeginDispatchDeparture(Cat);b.DispatchConversation.Current.node=1;Good(b,"save_game",slot:1);Good(b,"load_game",slot:1);check(b.DispatchConversation.Current.node==1,"Departure position lost");
            b.DispatchConversation.Current.node=4;Good(b,"save_game",slot:2);Good(b,"load_game",slot:2);check(b.DispatchConversation.Current.node==4,"Choice position lost");
            double funds=b.Simulation.State.funds;var row=b.DispatchConversation;row.Current.branch_id="cancelled";row.Current.node=2;CafeDispatchDialogue.Finish(row);CafeDispatchDialogue.Finish(row);Good(b,"save_game",slot:9);Good(b,"load_game",slot:9);check(b.Simulation.State.funds==funds && b.Simulation.State.dispatches.Count==0 && b.DispatchConversation.Current.viewed_branches.Length==1,"Cancel changed gameplay");
            b.BeginDispatchDeparture(Cat);string payload=Payload(b,"dispatch_general",CafeDispatchDialogue.Destination);var reply=Raw(b,payload);check(reply.result==UnityWebRequest.Result.Success,"Departure failed");string after=JsonUtility.ToJson(b.Simulation.State);check(Raw(b,payload).text==reply.text && after==JsonUtility.ToJson(b.Simulation.State),"Departure resend repeated");check(b.DispatchConversation.Current.branch_id=="departed" && b.Simulation.State.funds==funds,"Departure charged money");
            row=b.DispatchConversation;row.Current.node=1;Good(b,"save_game",slot:3);Good(b,"load_game",slot:3);check(b.DispatchResultPending && Send(b,"day_off").result==UnityWebRequest.Result.ProtocolError,"Unfinished departure result advanced");
            row=b.DispatchConversation;row.Current.node=3;CafeDispatchDialogue.Finish(row);check(!b.DispatchResultPending && row.departure.viewed_branches.Length==2,"Departure completion lost cancel record");b.BeginDispatchEvent(row.event_id);row.Current.node=1;Good(b,"save_game",slot:4);Good(b,"load_game",slot:4);check(b.DispatchConversation.stage=="travelling" && b.DispatchConversation.Current.node==1,"Travel position lost");row=b.DispatchConversation;row.Current.node=3;CafeDispatchDialogue.Finish(row);b.DispatchConversationOpen=false;Good(b,"day_off");ClearStore(b);b.PrepareDispatchConversation();
            row=b.DispatchConversation;check(row.stage=="return" && b.Simulation.DispatchWaiting,"Return conversation missing");row.Current.node=3;Good(b,"save_game",slot:5);Good(b,"load_game",slot:5);check(Send(b,"day_off").result==UnityWebRequest.Result.ProtocolError,"Unclaimed return advanced");
            funds=b.Simulation.State.funds;payload=Payload(b,"receive_general",row.event_id);reply=Raw(b,payload);check(reply.result==UnityWebRequest.Result.Success,"Receipt failed");after=JsonUtility.ToJson(b.Simulation.State);check(Raw(b,payload).text==reply.text && after==JsonUtility.ToJson(b.Simulation.State),"Receipt resend paid twice");check(Send(b,"receive_general",row.event_id).result==UnityWebRequest.Result.ProtocolError && after==JsonUtility.ToJson(b.Simulation.State),"New receipt request paid twice");
            row=b.DispatchConversation;check(row.Current.branch_id=="received" && b.Simulation.State.funds==funds+125 && b.Simulation.ItemInventory().Count(i=>i.source==row.event_id)==1 && b.Simulation.State.growth.Single(g=>g.cat_id==Cat).dispatch==1,"Reward, item or XP differs");row.Current.node=1;Good(b,"save_game",slot:6);var fresh=new LocalCafeBackend(folder);Good(fresh,"load_game",slot:6);check(fresh.DispatchConversation.Current.node==1 && fresh.DispatchResultPending,"Fresh result resume lost");
            row.Current.node=3;CafeDispatchDialogue.Finish(row);CafeDispatchDialogue.Finish(row);Good(b,"save_game",slot:7);check(!b.ConversationBlocksProgress && row.Current.viewed_branches.Length==1,"Completion duplicated");
            var save=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-7.json")));save.slot=8;save.dispatch_conversations=null;save.dispatch_conversation_selected=null;File.WriteAllText(Path.Combine(folder,"slot-8.json"),JsonUtility.ToJson(save));Good(b,"load_game",slot:8);check(b.DispatchConversations.Length==0 && !b.BeginDispatchEvent(row.event_id) && b.DispatchConversations.Length==0,"Old resolved save fabricated viewing");
            Good(b,"load_game",slot:6);save=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-6.json")));save.slot=10;save.dispatch_conversations[0].returning.node=99;File.WriteAllText(Path.Combine(folder,"slot-10.json"),JsonUtility.ToJson(save));after=JsonUtility.ToJson(b.Simulation.State);string meta=JsonUtility.ToJson(b.DispatchConversation);check(Send(b,"load_game",slot:10).result==UnityWebRequest.Result.ProtocolError && after==JsonUtility.ToJson(b.Simulation.State) && meta==JsonUtility.ToJson(b.DispatchConversation),"Invalid save replaced live state");
            Good(b,"load_game",slot:7);b.BeginDispatchDeparture(Cat);Good(b,"dispatch_general",CafeDispatchDialogue.Destination);check(b.DispatchConversations.Length==2 && b.DispatchConversations[0].returning.completed && b.DispatchConversations[1].Current.branch_id=="departed","Later trip overwrote old completion");
            return count;
        }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void Install()
        {
            var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--catcafe-dispatch-conversation-check");if(i<0 || FindObjectOfType<StandaloneDispatchConversationSmoke>()!=null)return;
            var go=new GameObject("Dispatch conversation verification");DontDestroyOnLoad(go);var qa=go.AddComponent<StandaloneDispatchConversationSmoke>();qa.output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(qa.output);Application.runInBackground=true;Application.logMessageReceived+=qa.Log;
            try{qa.checks+=BackendChecks(Path.Combine(qa.output,"cases"),Array.IndexOf(args,"--dispatch-conversation-restart")>=0);qa.Check(StandaloneDispatchSmoke.Run(Path.Combine(qa.output,"existing-rules"))>0,"Existing dispatch rules regression");qa.backend=new LocalCafeBackend(Path.Combine(qa.output,"ui"));CafeBackends.UseLocal(qa.backend);qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}
        }
        void Apply(DispatchConversationPanel ui){typeof(PythonStateClient).GetMethod("Accept",Hidden).Invoke(ui.GetComponent<PythonStateClient>(),new object[]{backend.View()});}
        IEnumerator Guard(){var run=Run();while(true){bool more;try{if(errors.Count>0)throw new Exception(string.Join("\n",errors));more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
        IEnumerator Run()
        {
            SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);
            var ui=FindObjectOfType<DispatchConversationPanel>();var owner=ui.GetComponent<PythonGeneralDispatchPanel>();var client=ui.GetComponent<PythonStateClient>();Check(ui!=null && !ui.Showing,"Day one dispatch hidden");owner.OpenOption(Cat,CafeDispatchDialogue.Destination);owner.Send();yield return null;Check(ui.Showing && backend.DispatchConversation.cat_id==Cat && !owner.panel.activeSelf,"Existing cat selection enters ADV");
            Canvas.ForceUpdateCanvases();Check(Vector2.Distance(ui.Panel.GetComponent<RectTransform>().rect.size,ui.Panel.GetComponentInParent<Canvas>().GetComponent<RectTransform>().rect.size)<1,"Full screen bounds");Check(ui.Panel.GetComponentsInChildren<Graphic>(true).All(g=>g.GetComponent<CanvasRenderer>()!=null),"Hidden mask renderer missing");
            typeof(AcquisitionConversationPanel).GetField("revealed",Hidden).SetValue(ui,0f);var surface=ui.Panel.GetComponentInChildren<ConversationAdvanceSurface>(true);ExecuteEvents.Execute(surface.gameObject,new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left},ExecuteEvents.pointerClickHandler);ui.Next();Check(backend.DispatchConversation.Current.node==0,"Same frame text skipped");yield return null;ui.Next();Check(backend.DispatchConversation.Current.node==1,"Next text failed");yield return null;
            backend.DispatchConversation.Current.node=4;Apply(ui);yield return null;var buttons=ui.Panel.GetComponentsInChildren<Button>(true);var yes=buttons.First(b=>b.name=="迎える");var no=buttons.First(b=>b.name=="見送る");Check(yes.interactable && no.interactable,"Departure buttons disabled");var cat=backend.Simulation.State.cats.Single(c=>c.id==Cat);cat.fatigue=60.01;Apply(ui);Check(!yes.interactable && no.interactable && ui.Panel.GetComponentsInChildren<Text>(true).Any(t=>t.text.Contains("疲労")),"Fatigue gate missing");cat.fatigue=0;cat.stamina=0;Apply(ui);Check(!yes.interactable && no.interactable,"Stamina gate missing");cat.stamina=100;Apply(ui);yield return null;
            double funds=backend.Simulation.State.funds;ui.Answer(false);ui.Answer(false);yield return null;Check(backend.DispatchConversation.Current.branch_id=="cancelled" && backend.Simulation.State.dispatches.Count==0 && backend.Simulation.State.funds==funds,"Cancel dispatched cat");ui.Close();ui.GetComponent<PythonEventListPanel>().ShowMenu(10);Check(ui.Showing && ui.GetComponent<PythonEventListPanel>().PendingFor(10)==1,"Cancelled result stranded without a dispatch record");backend.DispatchConversation.Current.node=2;Apply(ui);yield return null;ui.Next();yield return null;
            owner.OpenOption(Cat,CafeDispatchDialogue.Destination);owner.Send();backend.DispatchConversation.Current.node=4;Apply(ui);yield return null;ui.Answer(true);ui.Answer(true);yield return new WaitForSecondsRealtime(2);Check(backend.Simulation.State.dispatches.Count==1 && backend.Simulation.State.cats.Single(c=>c.id==Cat).activity=="dispatched" && backend.Simulation.State.funds==funds,"Departure duplicated or charged");Check(backend.DispatchConversation.Current.branch_id=="departed" && !client.CanDayOff,"Departure result did not stop");backend.DispatchConversation.Current.node=3;Apply(ui);yield return null;ui.Next();yield return null;Check(!ui.Showing && !client.Automatic,"Departure did not finish manually");
            string id=backend.DispatchConversation.event_id;owner.OpenReturn(id);Check(ui.Showing && backend.DispatchConversation.stage=="travelling","Travel view missing");int day=backend.Simulation.State.day;ui.Close();Check(!backend.ConversationBlocksProgress && backend.Simulation.State.day==day,"Read-only travel advanced day or blocked after close");Good(backend,"day_off");ClearStore(backend);Apply(ui);yield return null;Check(ui.Showing && backend.DispatchConversation.stage=="return" && backend.Simulation.DispatchWaiting,"Return did not activate");
            backend.DispatchConversation.Current.node=3;Apply(ui);yield return null;ui.Answer(false);yield return null;Check(!ui.Showing && backend.Simulation.DispatchWaiting && !client.CanDayOff,"Postpone consumed return");ui.GetComponent<PythonEventListPanel>().ShowMenu(10);Check(ui.Showing && !owner.panel.activeSelf,"Unclaimed return cannot reopen above old panel");yield return null;
            funds=backend.Simulation.State.funds;ui.Answer(true);ui.Answer(true);yield return new WaitForSecondsRealtime(2);Check(backend.DispatchConversation.Current.branch_id=="received" && backend.Simulation.State.funds==funds+125 && backend.Simulation.ItemInventory().Length==1,"UI receipt duplicated");ui.Close();Check(backend.DispatchResultPending && !client.CanDayOff && backend.ConversationProgressReason.Contains("派遣"),"Hidden receipt result lost reason");ui.GetComponent<PythonEventListPanel>().ShowMenu(10);Check(ui.Showing,"Receipt result stranded");
            buttons=ui.Panel.GetComponentsInChildren<Button>(true);buttons.First(b=>b.name=="バックログ").onClick.Invoke();yield return null;Canvas.ForceUpdateCanvases();var history=ui.HistoryScroll;Check(history.content.rect.height>=history.content.GetComponent<Text>().preferredHeight-1,"Backlog clipped");history.verticalNormalizedPosition=0;yield return null;Check(history.verticalNormalizedPosition<.01f || history.content.rect.height<=history.viewport.rect.height,"Backlog bottom unreachable");buttons.First(b=>b.name=="バックログ").onClick.Invoke();yield return null;
            backend.DispatchConversation.Current.node=3;Apply(ui);yield return null;ui.Next();yield return null;Check(!ui.Showing && !backend.DispatchResultPending && client.CanDayOff && !client.Automatic,"Receipt finish did not release progression");
            string manual=Path.Combine(output,"manual");Directory.CreateDirectory(manual);bool load=Array.IndexOf(Environment.GetCommandLineArgs(),"--dispatch-manual-load")>=0;if(!load)File.Copy(Path.Combine(output,"cases/slot-5.json"),Path.Combine(manual,"slot-5.json"),true);backend=new LocalCafeBackend(manual);Good(backend,"load_game",slot:load?8:5);CafeBackends.UseLocal(backend);Apply(ui);yield return new WaitForSecondsRealtime(1);
            Check(errors.Count==0,"Unity errors");completed=true;File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" dispatch conversation checks; zero Unity errors. Departure/cancel/travel/postpone/receipt, saving, duplicate prevention, old saves, conditions, backlog and manual resume.");
